def seg_dist(p,a,b):
    ax,ay=a; bx,by=b; px,py=p
    dx,dy=bx-ax,by-ay
    if dx==dy==0: return ((px-ax)**2+(py-ay)**2)**.5
    t=max(0,min(1,((px-ax)*dx+(py-ay)*dy)/(dx*dx+dy*dy)))
    return ((px-(ax+t*dx))**2+(py-(ay+t*dy))**2)**.5
for iid,it in ITEMS.items():
    bad=[]
    for name,x,y,r,st in TREES:
