        d=min(seg_dist((x,y),s['pts'][i],s['pts'][i+1]) for s in it['segs'] for i in range(len(s['pts'])-1))
        if d<r: bad.append((name,round(d,1),r))
    print(iid,'tree conflicts:',bad)
