def duct_id_for(it,methods):
    if 'HDD' in methods: return 4.551 if it['duct']==5 else 5.420,0.30
    if 'JB' in methods: return (6.065 if it['duct']==6 else 5.047),0.40
    if it['id']=='C05': return 5.047,0.40
    if it['duct']==6: return 6.265,0.35
    return 5.263,0.35
def pull_calc(it):
    out=[]; pts=it['pts']; L=it['L']; ssize=it['size']; sets=it['sets']
    stops=[('START',0.0)]+[(sid,d) for sid,xy,d in it['struct']]+[('END',L)]
    W=3*CABLE[ssize][2]; d=CABLE[ssize][1]
    lim=min(0.006*CABLE[ssize][0]*2,10000)
    isb=(it['id']=='C05')
    def one_dir(pl,term_start,term_end):
        T=100.0; sw=0.0
        r=7.0 if isb else 8.0
        def sbp(T,R,cfg):
            return (3*wc-2)*T/(3*R) if cfg=='crad' else wc*T/(2*R)
        if term_start:
            T+=W*r
            T*=math.exp(wc*f*math.pi/2); sw=max(sw,sbp(T,3.0,cfg))
        # accumulate straight lengths with bends at interior vertices
        for j in range(len(pl)-1):
            T+=wc*f*W*math.dist(pl[j],pl[j+1])
            if j<len(pl)-2:
                a1=math.atan2(pl[j+1][1]-pl[j][1],pl[j+1][0]-pl[j][0])
                a2=math.atan2(pl[j+2][1]-pl[j+1][1],pl[j+2][0]-pl[j+1][0])
                th=abs((a2-a1+math.pi)%(2*math.pi)-math.pi)
                if th>0.02:
                    T*=math.exp(wc*f*th); sw=max(sw,sbp(T,3.0 if isb else 25.0,cfg))
        if term_end:
            T*=math.exp(wc*f*math.pi/2); sw=max(sw,sbp(T,3.0,cfg))
        return T,sw
    for i in range(len(stops)-1):
        fid,d0=stops[i]; tid,d1=stops[i+1]
        pl=sub_poly(pts,d0,d1); ln=d1-d0
        meth=set()
        for s in it['segs']:
            if s['d1']>d0+1e-6 and s['d0']<d1-1e-6: meth.add(s['method'])
        if isb: meth={'RMC'}
        ID,f=duct_id_for(it,meth)
        Dd=ID/d
        if Dd<2.8: cfg='tri'; wc=1/math.sqrt(1-(d/(ID-d))**2)
        else: cfg='crad'; wc=1+(4/3)*(d/(ID-d))**2
        Tf,swf=one_dir(pl,i==0,i==len(stops)-2)
        Tb,swb=one_dir(list(reversed(pl)),i==len(stops)-2,i==0)
        if swb<swf-1e-9 or (abs(swb-swf)<=1e-9 and Tb<Tf):
            T,sw,frm,to=Tb,swb,tid,fid
        else:
            T,sw,frm,to=Tf,swf,fid,tid
        fill=3*d*d/(ID*ID)*100
        out.append(dict(pull_id=f"P{i+1:02d}",frm=frm,to=to,length=round(ln,3),T=round(T,1),sw=round(sw,1),
                        jam=round(Dd,3),fill=round(fill,1),limit=lim,cfg=cfg,wc=round(wc,4),f=f,ID=ID))
    return out
